    "nominate-ph-email": "usted@ejemplo.com",
    "nominate-label-residence": "País de Residencia",
    "nominate-ph-residence": "p. ej., Estados Unidos",
    "nominate-submit": "Enviar Nominación",
    "nominate-disclaimer": "Al enviar, confirma que la información es precisa. Las nominaciones se publican y son revisadas por la comunidad de Custodia.",
    "nominate-next-eyebrow": "QUÉ SUCEDE DESPUÉS",
    "nominate-next-1": "Su nominación se publica en un plazo de 7 días.",
    "nominate-next-2": "Los Custodios la revisan y discuten en el foro global.",
    "nominate-next-3": "En la próxima Asamblea Trimestral, los Custodios votan qué sitios asumir.",
    "nominate-next-4": "Los sitios seleccionados entran a negociación del Pacto de Soberanía.",
    "nominate-next-5": "Se le acreditará como nominador y se le invitará a la Gran Apertura.",
    "vote-eyebrow": "ASAMBLEA TRIMESTRAL · Q3 2026",
    "vote-h1": "El mundo decide qué salvar a continuación.",
    "vote-intro": "Seis sitios están en votación este trimestre. Los Custodios pueden distribuir su peso de voto entre varios sitios. Los dos con mayor puntaje entran al ciclo de negociación del Pacto de Soberanía.",
    "vote-window-label": "CIERRE DE LA VENTANA DE VOTACIÓN",
    "vote-window-val": "14 días · 6 horas · 23 minutos",
    "vote-weight-label": "TU PESO DE VOTO",
    "vote-weight-val": "100 votos (Custodio Oro)",
    "vote-current-label": "VOTOS ACTUALES",
    "vote-allocate": "Asignar Votos",
    "vote-1-country": "EGIPTO · NOMINADO POR A. ELDESSOUKY",
    "vote-1-name": "Acueducto del Cairo Histórico",
    "vote-1-body": "Un acueducto mameluco del siglo XIV. Secciones colapsaron en 2025 sin respuesta del gobierno. Invadido por asentamientos informales.",
    "vote-1-tally": "12,488 de 1,203 Custodios",
    "vote-2-country": "GHANA · NOMINADO POR K. ASANTE",
    "vote-2-name": "São Jorge da Mina (Castillo de Elmina)",
    "vote-2-body": "Fortaleza portuguesa del siglo XV en el Golfo de Guinea. Sitio UNESCO. Punto sagrado y doloroso del comercio transatlántico de esclavos.",
    "vote-2-tally": "10,221 de 987 Custodios",
    "vote-3-country": "ETIOPÍA · NOMINADO POR S. GIRMA",
    "vote-3-name": "Estabilización del Techo de Bet Maryam",
    "vote-3-body": "Una de las once iglesias monolíticas excavadas en roca de Lalibela. Las cubiertas protectoras de UNESCO han fallado; el techo requiere intervención inmediata.",
    "vote-3-tally": "9,114 de 902 Custodios",
